import { GlobeView, createRobotPreview } from './globe.js';
import { Expedition } from './expedition.js';
import { SITES, TARGETS, EARTH_SITES, SOURCES, METHOD, loadTerrain, analyzeTerrain, compareTerrains, sampleTerrain } from './science.js';
import { icon, escapeHTML as esc } from './icons.js';
import {initSearchUI,SEARCH_SOURCES} from './search-ui.js';
import {restoreSearchWindows,saveSearchWindows,validSearchWindow} from './search-cache.js';

const $=selector=>document.querySelector(selector),$$=selector=>[...document.querySelectorAll(selector)],fmt=(value,digits=0)=>Number(value).toLocaleString('en-US',{maximumFractionDigits:digits,minimumFractionDigits:digits});
const state={view:'explore',body:'mars',targetId:'jezero',earthId:'wadi-rum',globeBody:'earth',task:'terrain',terrains:new Map(),stats:new Map(),weights:{slope:.65,relief:.35},rankings:[],evidenceOpen:false,ready:false,observations:[],customSites:[],searchCoverage:null};
try{const saved=JSON.parse(localStorage.getItem('terramatch-observations')||'[]');if(Array.isArray(saved))state.observations=saved.filter(o=>o&&typeof o.siteId==='string'&&Number.isFinite(o.height));}catch{}
let globe,preview,expedition,searchUI,previousFocus,latestTelemetry;const thumbs=new Map();
const allSites=()=>[...SITES,...state.customSites],earthSites=()=>allSites().filter(site=>site.body==='earth'&&site.comparisonEligible!==false),allSources=()=>[...SOURCES,...SEARCH_SOURCES];
const siteById=id=>allSites().find(site=>site.id===id),target=()=>siteById(state.targetId),earth=()=>siteById(state.earthId),statsFor=id=>state.stats.get(id),dataFor=id=>state.terrains.get(id);
const coord=(value,positive,negative)=>`${Math.abs(value).toFixed(2)}° ${value<0?negative:positive}`;
const coordinates=site=>`${coord(site.lat,'N','S')} · ${coord(site.lon,'E','W')}`;
const sourceById=id=>allSources().find(source=>source.id===id);
const sourceChip=id=>{const source=sourceById(id);return source?`<a class="source-chip" href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${icon('source')} ${esc(id==='mola'?'NASA · MOLA':id==='lola'?'NASA · LOLA':id==='srtm'?'Skadi elevation':source.agency.split('/')[0])}</a>`:'';};

function toast(message,error=false){const el=document.createElement('div');el.className=`toast ${error?'error':''}`;el.innerHTML=icon(error?'warning':'check')+`<span>${esc(message)}</span>`;$('#toast-region').append(el);setTimeout(()=>el.remove(),5000);}
function webglError(container){container.insertAdjacentHTML('beforeend',`<div class="webgl-error">${icon('globe')}<h3>3D needs WebGL</h3><p>Enable hardware acceleration or try a browser with WebGL 2 support. The terrain comparisons and source data remain available.</p><button class="button button-outline" data-open-compare>Open data comparison</button></div>`);container.querySelector('[data-open-compare]').onclick=()=>showView('compare');}

function terrainThumb(site){if(thumbs.has(site.id))return thumbs.get(site.id);const data=dataFor(site.id),stats=statsFor(site.id);if(!data)return 'assets/jezero-panorama.jpg';const canvas=document.createElement('canvas');canvas.width=192;canvas.height=128;const ctx=canvas.getContext('2d'),image=ctx.createImageData(192,128),moon=site.body==='moon';for(let y=0;y<128;y++)for(let x=0;x<192;x++){const u=x/191,v=y/127,h=sampleTerrain(data,u,v),left=sampleTerrain(data,u-.008,v),right=sampleTerrain(data,u+.008,v),up=sampleTerrain(data,u,v-.008),down=sampleTerrain(data,u,v+.008),shade=Math.max(.4,Math.min(1.3,.85+(left-right+up-down)/120)),level=(h-stats.min)/(stats.relief||1),i=(y*192+x)*4;image.data[i]=(moon?100:112+level*90)*shade;image.data[i+1]=(moon?103:79+level*80)*shade;image.data[i+2]=(moon?108:52+level*56)*shade;image.data[i+3]=255;}ctx.putImageData(image,0,0);const url=canvas.toDataURL();thumbs.set(site.id,url);return url;}
function siteImage(site){if(site.id==='jezero')return 'assets/jezero-panorama.jpg';if(site.id==='wadi-rum')return 'assets/wadi-rum-nasa.jpg';return terrainThumb(site);}
function computeRankings(){const a=dataFor(state.targetId);if(!a)return;state.rankings=earthSites().filter(site=>dataFor(site.id)).map(site=>({site,...compareTerrains(a,dataFor(site.id),state.weights)})).sort((a,b)=>b.score-a.score);}
function renderCandidates(){const cards=$('#candidate-cards');cards.innerHTML=state.rankings.map((item,index)=>`<button class="candidate-card ${item.site.id===state.earthId?'selected':''}" data-candidate="${item.site.id}" aria-pressed="${item.site.id===state.earthId}"><img class="candidate-thumb" src="${siteImage(item.site)}" alt="${esc(item.site.id==='wadi-rum'?'NASA orbital image of Wadi Rum':item.site.name+' elevation hillshade')}"><span class="candidate-rank">${index+1}</span><div><h3>${esc(item.site.name)}</h3><p>${esc(item.site.country)}</p>${item.site.origin?`<span class="candidate-origin">${item.site.origin==='automatic'?'AUTO DISCOVERY':'MANUAL SELECTION'}</span>`:''}<span class="candidate-link">Review terrain evidence ↗</span></div></button>`).join('');cards.querySelectorAll('[data-candidate]').forEach(button=>button.onclick=()=>selectEarth(button.dataset.candidate));$('#candidate-count').textContent=`${state.rankings.length} regions · terrain-only ranking`;}
function selectEarth(id){if(!earthSites().some(s=>s.id===id))return;state.earthId=id;renderCandidates();if(state.globeBody==='earth'){globe?.setSites(earthSites(),id);globe?.focusSite(earth());}if(state.view==='compare')renderComparison();if(state.evidenceOpen)renderExpeditionEvidence();}
function renderDestination(){const site=target(),stats=statsFor(site.id);$('#destination-name').textContent=site.name;$('#destination-body').textContent=site.country;$('#destination-coordinate').innerHTML=coord(site.lat,'N','S')+'<br>'+coord(site.lon,'E','W');$('#destination-description').textContent=site.description;$('#destination-image').style.backgroundImage=`linear-gradient(0deg,#241b1488,transparent 80%),url('${siteImage(site)}')`;$('#destination-image').classList.toggle('moon',site.body==='moon');$('#destination-image-label').textContent=site.id==='jezero'?'NASA / JPL · MASTCAM-Z PANORAMA':'LOLA ELEVATION · SHADED RELIEF';
  $('#destination-features').innerHTML=[['terrain','Real terrain',stats?`${fmt(stats.relief)} m of relative relief across a 32 km study window.`:'Preparing elevation data.'],['compare','Earth comparisons',`${earthSites().length} inland candidates. Transparent slope and relief measurements.`],['source','Traceable evidence','500 m sampling · slopes measured over a 1 km baseline.']].map(([i,title,text])=>`<div class="destination-feature">${icon(i)}<div><h3>${title}</h3><p>${esc(text)}</p></div></div>`).join('');$('#destination-source-chips').innerHTML=sourceChip(site.sourceIds[0]);
  $$('[data-globe="target"]').forEach(button=>button.textContent=site.country);$('#enter-expedition').disabled=!dataFor(site.id);}
function setTarget(id){const site=siteById(id);if(!site||site.body==='earth')return;state.targetId=id;state.body=site.body;$$('[data-body]').forEach(button=>button.classList.toggle('active',button.dataset.body===site.body));$('#target-select').innerHTML=TARGETS.filter(s=>s.body===state.body).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');$('#target-select').value=id;computeRankings();renderCandidates();renderDestination();if(state.globeBody!=='earth'){state.globeBody=site.body;globe?.setPlanet(site.body,TARGETS,id);}if(state.view==='compare')renderComparison();}
function setGlobeBody(body){state.globeBody=body==='earth'?'earth':target().body;$$('[data-globe]').forEach(button=>button.classList.toggle('active',button.dataset.globe===(body==='earth'?'earth':'target')));globe?.setPlanet(state.globeBody,state.globeBody==='earth'?earthSites():TARGETS,state.globeBody==='earth'?state.earthId:state.targetId);$('.globe-source').textContent=state.globeBody==='earth'?'NASA Blue Marble · visual globe':state.globeBody==='mars'?'Solar System Scope / INOVE · CC BY 4.0':'Lunar visual texture · context only';}
function showView(view){if(view==='expedition'&&!expedition?.data){startExpedition();return;}state.view=view;$$('.view').forEach(section=>section.classList.toggle('hidden',section.id!==`${view}-view`));$$('[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view===view));globe?.setActive(view==='explore');preview?.setActive(view==='explore');expedition?.setActive(view==='expedition');if(view==='compare')renderComparison();if(view==='sources')renderSources();window.scrollTo({top:0,behavior:'instant'});if(view==='expedition')expedition.renderer?.domElement.focus({preventScroll:true});}

function profileSVG(a,b,{mini=false}={}){const w=mini?300:1000,h=mini?90:235,p=mini?8:42,profiles=[a.profileRelative,b.profileRelative],max=Math.max(...profiles.flat(),1)*1.07;const line=values=>values.map((v,i)=>`${p+i/(values.length-1)*(w-p*2)},${h-p-v/max*(h-p*2)}`).join(' ');let grid='';if(!mini){for(let j=0;j<4;j++){const y=h-p-j/3*(h-p*2);grid+=`<line class="chart-grid" x1="${p}" x2="${w-p}" y1="${y}" y2="${y}"/><text class="chart-axis" x="${p-8}" y="${y+4}" text-anchor="end">${fmt(max*j/3)}</text>`;}for(let i=0;i<5;i++){const x=p+i/4*(w-p*2);grid+=`<text class="chart-axis" x="${x}" y="${h-10}" text-anchor="middle">${i*8} km</text>`;}}
  return `<svg class="${mini?'mini-profile':'chart-svg'}" viewBox="0 0 ${w} ${h}" role="img" aria-label="Terrain profiles, elevations relative to each window minimum. Both profiles span 32 kilometers.">${grid}<polyline fill="none" stroke="#ff9b50" stroke-width="${mini?2:2.5}" points="${line(profiles[0])}"/><polyline fill="none" stroke="#65d3c9" stroke-width="${mini?2:2.5}" points="${line(profiles[1])}"/></svg>`;}
function histogramSVG(a,b){const w=1000,h=235,p=42,bins=['0–2°','2–5°','5–10°','10–20°','20–35°','35–90°'];let svg='';for(let j=0;j<=4;j++){const y=h-p-j/4*(h-p*2);svg+=`<line class="chart-grid" x1="${p}" x2="${w-p}" y1="${y}" y2="${y}"/><text class="chart-axis" x="${p-8}" y="${y+4}" text-anchor="end">${j*25}%</text>`;}const cell=(w-p*2)/6;for(let i=0;i<6;i++){const x=p+i*cell+cell*.22,bw=cell*.24;for(const [index,stats] of [a,b].entries()){const bh=stats.slopeHistogram[i]*(h-p*2);svg+=`<rect x="${x+index*bw}" y="${h-p-bh}" width="${bw-4}" height="${bh}" rx="2" fill="${index?'#65d3c9':'#ff9b50'}" opacity=".85"><title>${esc(index?earth().name:target().name)}: ${(stats.slopeHistogram[i]*100).toFixed(1)}% of slope samples</title></rect>`;}svg+=`<text class="chart-axis" x="${p+(i+.5)*cell}" y="${h-14}" text-anchor="middle">${bins[i]}</text>`;}return `<svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Distribution of terrain slopes across matched one-kilometer gradient baselines">${svg}</svg>`;}
function miniLegend(){return `<div class="profile-legend"><span>${esc(target().name)}</span><span>${esc(earth().name)}</span></div>`;}
function metricsHTML(stats){return `<div class="comparison-metrics"><div><div class="metric-value">${fmt(stats.relief)}<small> m</small></div><p class="metric-label">Relative relief</p></div><div><div class="metric-value">${fmt(stats.slopeMean,2)}<small>°</small></div><p class="metric-label">Mean coarse slope</p></div><div><div class="metric-value">${fmt(stats.slopeP90,2)}<small>°</small></div><p class="metric-label">90th percentile slope</p></div></div>`;}
function renderComparison(){const a=statsFor(state.targetId),b=statsFor(state.earthId);if(!a||!b){$('#comparison-workspace').innerHTML=`<div class="panel empty-state"><h2>Preparing the comparison</h2><p>Real elevation datasets are loading. Please try again shortly.</p></div>`;return;}const result=compareTerrains(dataFor(state.targetId),dataFor(state.earthId),state.weights),t=target(),e=earth();
  $('#comparison-workspace').innerHTML=`<div class="comparison-selectors"><label>Planetary study area<select id="comparison-target">${TARGETS.map(s=>`<option value="${s.id}" ${s.id===t.id?'selected':''}>${esc(s.name)} · ${s.country}</option>`).join('')}</select></label><label>Earth candidate<select id="comparison-earth">${earthSites().map(s=>`<option value="${s.id}" ${s.id===e.id?'selected':''}>${esc(s.name)} · ${esc(s.country)}</option>`).join('')}</select></label></div>
    <div class="comparison-grid">${[[t,a,false],[e,b,true]].map(([site,stats,isEarth])=>`<article class="comparison-site panel ${isEarth?'earth':''}"><div class="site-planet">${isEarth?'EARTH ANALOG CANDIDATE':site.country+' TARGET'}</div><h2>${esc(site.name)}</h2><p>${esc(site.category)} · ${coordinates(site)}</p>${metricsHTML(stats)}<div class="source-chips">${sourceChip(site.sourceIds[0])}<button class="source-chip" data-explore-site="${site.id}">${icon('play')} Explore this terrain</button></div></article>`).join('')}</div>
    <div class="method-summary panel">${icon('compare')}<div><h2>Terrain resemblance index: ${fmt(result.score,1)} / 100</h2><p>This index compares slope distributions and relative relief within equal 32 × 32 km windows. It is a terrain-only heuristic, not a probability or a recommendation for a mission. Active weights: ${fmt(result.components[0].weight*100)}% slope distribution, ${fmt(result.components[1].weight*100)}% relative relief.</p></div><button class="text-link" id="comparison-method">Method ↗</button></div>
    <section class="comparison-chart panel"><div class="chart-title"><div><h2>How steep is the landscape?</h2><p>Share of interior samples in each slope range · gradient baseline: 1 km</p></div>${miniLegend()}</div>${histogramSVG(a,b)}</section>
    <section class="comparison-chart panel"><div class="chart-title"><div><h2>A cross-section through each study area</h2><p>Middle-row profile · elevation above each window's minimum in meters · distance in kilometers</p></div>${miniLegend()}</div>${profileSVG(a,b)}</section>
    <div class="comparison-columns"><article class="panel comparison-notes"><h2>Where the analogy helps</h2><p>${esc(e.description)}</p><ul>${e.useCases.map(text=>`<li>${esc(text)}</li>`).join('')}</ul><p>Measured slope and relief resemblance can help select a candidate for further field assessment. Similar terrain does not imply matching geological history or materials.</p><div class="source-chips" style="margin-top:14px">${e.sourceIds.slice(1).map(sourceChip).join('')}</div></article><article class="panel comparison-notes"><h2>Where the analogy breaks down</h2><ul>${[...t.limitations.slice(0,1),...e.limitations].map(text=>`<li>${esc(text)}</li>`).join('')}</ul><p>Temperature, ice, mineralogy and biology are unassessed. Gravity, atmosphere and radiation are not reproduced.</p></article></div>
    <section class="panel comparison-notes ranking-list"><h2>Compare the other candidates</h2>${state.rankings.map((item,i)=>`<div class="ranking-row"><span class="rank-number">0${i+1}</span><div><h3>${esc(item.site.name)} <span style="font-size:10px;color:var(--muted)">· ${esc(item.site.country)}</span></h3><p>${fmt(item.score,1)} / 100 · terrain resemblance index${item.site.id==='amboy'?' · established reference site':''}</p><div class="score-bar"><i style="width:${item.score}%"></i></div></div><button data-select-comparison="${item.site.id}">Review evidence ↗</button></div>`).join('')}</section>
    <section class="panel comparison-notes ranking-list"><h2>Field notebook <span style="font-size:11px;color:var(--muted)">· ${state.observations.length} saved observations</span></h2><p>Inspect terrain during an expedition to save a geolocated elevation and coarse slope sample. Notes stay in this browser.</p><div style="display:flex;gap:12px;margin-top:16px"><button class="button button-outline button-small" id="download-observations">Export observations</button><button class="button button-outline button-small" id="download-evidence">Download evidence JSON</button></div>${state.observations.slice(-5).reverse().map(note=>`<div class="ranking-row"><div><h3>${esc(note.siteName)}</h3><p>${esc(coordinates(note))} · ${fmt(note.height,1)} m · ${fmt(note.slope,2)}° coarse slope</p>${note.note?`<p>${esc(note.note)}</p>`:''}</div></div>`).join('')}</section>`;
  $('#comparison-target').onchange=e=>setTarget(e.target.value);$('#comparison-earth').onchange=e=>selectEarth(e.target.value);$('#comparison-method').onclick=showMethod;$$('[data-select-comparison]').forEach(button=>button.onclick=()=>selectEarth(button.dataset.selectComparison));$$('[data-explore-site]').forEach(button=>button.onclick=()=>startExpedition(siteById(button.dataset.exploreSite)));$('#download-observations').onclick=exportObservations;$('#download-evidence').onclick=exportEvidence;
}

function renderSources(){const inUse=new Set(['mola','lola','srtm','srtm-nasa']);$('#sources-content').innerHTML=`<div class="method-summary panel">${icon('source')}<div><h2>Real terrain. A deliberately bounded comparison.</h2><p>The expedition terrain and charts use bundled subsets of NASA MOLA, NASA LOLA and openly distributed Skadi terrain. Six reference grids are bundled locally. Manual and automatic searches retrieve additional Earth windows online; the most recent windows are cached in this browser. New searches depend on the public terrain service.</p></div></div>
    <div class="method-grid"><article class="panel"><h2>How we compare</h2><ol><li>Extract 32 × 32 km windows around named study locations.</li><li>Sample all windows onto a 65 × 65 grid at 500 m spacing.</li><li>Calculate interior slopes from central differences over a 1 km baseline.</li><li>Compare six-bin slope distributions using total-variation distance.</li><li>Compare relative relief with a bounded logarithmic difference.</li><li>Combine those distances using the selected weights.</li></ol><p>Default index = 100 × [1 − (0.65 × slope distance + 0.35 × relief distance)]. Relief distance = min(1, |ln((relief A + 1) / (relief B + 1))| / ln 4). We never compare raw absolute elevations across planetary datums.</p></article><article class="panel"><h2>What this experience represents</h2><p>Height geometry comes from the identified DEM subsets. Color, lighting and fine surface texture are visual treatments. The robot, lander and scattered rocks are original rendered objects; they are not mapped geological evidence.</p><ul><li>The explorer avatar is enlarged for navigation. Display units are not robot engineering dimensions.</li><li>Rocket arrival, leg animation and keyboard movement are not validated flight, soil or mobility simulations.</li><li>Sampling at 500 m does not create 500 m native information where a source is coarser.</li><li>The scene's lighting does not reconstruct lunar permanent shadow.</li><li>No land-access, field-safety, landing-safety or base-suitability recommendation is made.</li></ul></article></div>
    <section class="panel comparison-notes"><h2>Loaded study windows</h2><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Location</th><th>Body</th><th>Center</th><th>Grid / extent</th><th>Status</th><th>Evidence</th></tr></thead><tbody>${allSites().map(site=>`<tr><td>${esc(site.name)}</td><td>${esc(site.country)}</td><td>${coordinates(site)}</td><td>65 × 65 / 32 km</td><td>${dataFor(site.id)?site.comparisonEligible===false?(site.id==='lanzarote'?'Excluded: coastal bathymetry':'Excluded: coarse land screen'):(site.origin?'On-demand / cached':'Bundled'):'Unavailable'}</td><td><button class="text-link" data-source-site="${site.id}">Inspect provenance ↗</button></td></tr>`).join('')}</tbody></table></div><p class="source-note">Lanzarote's window includes ocean bathymetry and is deliberately excluded from the inland terrain ranking. Amboy is an established field-study reference, not a new discovery. Al Wahbah and Wadi Rum are candidates for further assessment; this app does not claim their analog status is newly established.</p></section>
    <div class="source-grid" style="margin-top:20px">${allSources().map(source=>`<article class="source-card panel"><p class="eyebrow">${inUse.has(source.id)?'TERRAIN DATA / DOCUMENTATION':'CONTEXT / CHALLENGE RESOURCE'}</p><h2>${esc(source.title)}</h2><p>${esc(source.note)}</p><a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.agency)} ${icon('external')}</a><p class="license-note">${esc(source.license)}</p></article>`).join('')}</div>
    <section class="panel comparison-notes" style="margin-top:20px"><h2>Visual asset credits</h2><p>Original procedural hexapod, cargo lander and rock meshes by TerraMatch. Three.js 0.181.1 (MIT). Earth and Moon visual textures distributed with Three.js examples. Mars globe texture: Solar System Scope / INOVE, CC BY 4.0; visual context only, including possible publisher gap-filling.</p><p style="margin-top:10px">Wadi Rum orbital image: NASA Earth Observatory / Jesse Allen and Robert Simmon, EO-1 ALI data courtesy NASA EO-1 team and USGS. Jezero panorama: NASA/JPL-Caltech/ASU/MSSS, PIA26378, enhanced color. Photographs are context images; they are not registered textures of the DEM.</p><div class="source-chips" style="margin-top:12px"><a class="source-chip" href="https://science.nasa.gov/earth/earth-observatory/wadi-rum-jordan-49945/" target="_blank" rel="noopener noreferrer">Wadi Rum image</a><a class="source-chip" href="https://science.nasa.gov/photojournal/perseverances-mid-climb-view-of-jezero-crater/" target="_blank" rel="noopener noreferrer">Jezero panorama</a><a class="source-chip" href="https://www.solarsystemscope.com/textures/" target="_blank" rel="noopener noreferrer">Mars texture &amp; license</a></div></section><p class="source-note">Created for NASA Space Apps Challenge 2026. Use of public NASA data does not imply NASA endorsement. Citations and original provider conditions remain applicable.</p>`;$$('[data-source-site]').forEach(button=>button.onclick=()=>showProvenance(siteById(button.dataset.sourceSite)));}

function openModal(html){previousFocus=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close" aria-label="Close dialog">${icon('close')}</button>${html}</section></div>`;$('#modal-root .modal-close').onclick=closeModal;$('#modal-root .modal-backdrop').onclick=e=>{if(e.target.classList.contains('modal-backdrop'))closeModal();};$('#modal-root .modal-close').focus();expedition?.setPaused(true);}
function closeModal(){if(!$('#modal-root').children.length)return;$('#modal-root').innerHTML='';if(state.view==='expedition'&&!$('#pause-overlay').classList.contains('hidden'))expedition?.setPaused(true);else expedition?.setPaused(false);if(state.view==='expedition')expedition?.renderer?.domElement.focus({preventScroll:true});else previousFocus?.focus?.({preventScroll:true});}
document.addEventListener('keydown',e=>{const modal=$('#modal-root .modal');if(!modal)return;if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeModal();}if(e.key==='Tab'){const items=[...modal.querySelectorAll('button,a[href],input,select,textarea')].filter(el=>!el.disabled);const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}},true);
function showMethod(){openModal(`<p class="eyebrow">EXPLAINABLE BY DESIGN</p><h2 id="modal-title">What makes a terrain analog?</h2><p>We compare equal 32 km study windows using two measurable properties: the distribution of coarse slopes, and relative relief. Each elevation grid is sampled at 500 m; gradients span a 1 km baseline.</p><h3>The terrain resemblance index</h3><p>100 × [1 − (weighted slope-distribution distance + weighted relief distance)]. Higher means more resemblance under these chosen measures. It is not a probability of mission suitability.</p><p>Default weights are 65% slope distribution and 35% relative relief. You can turn either characteristic off in mission setup. Materials, temperature, ice, biology, access and operating conditions need separate evidence.</p><div class="limit-callout">${icon('warning')}<div><h3>Match a purpose, not an entire planet.</h3><p>Terrain can help you shortlist field environments. Earth does not reproduce lunar or Martian gravity, atmosphere or radiation.</p></div></div><button class="button button-primary" id="method-sources">Read the data &amp; method</button>`);$('#method-sources').onclick=()=>{closeModal();showView('sources');};}
function showProvenance(site){const data=dataFor(site.id);openModal(`<p class="eyebrow">SOURCE RECORD</p><h2 id="modal-title">${esc(site.name)}</h2><p>Actual source metadata bundled with this terrain subset. Elevations are in meters in the product's own reference datum.</p><div class="source-chips">${site.sourceIds.map(sourceChip).join('')}</div><pre style="white-space:pre-wrap;overflow-wrap:anywhere;font-size:10px;color:#a8c0cf;line-height:1.7;margin-top:20px">${esc(JSON.stringify(data?{center:data.center,bounds:data.bounds,projection:data.projection,gridSpacingMeters:data.gridSpacingMeters,units:data.units,source:data.source,retrievedAt:data.retrievedAt,comparisonEligible:data.comparisonEligible}: {status:'Data unavailable'},null,2))}</pre>`);}

async function startExpedition(site=target()){
  if(!state.ready||!dataFor(site.id)){toast('This terrain is not ready yet. Check Sources for availability.',true);return;}
  if(!expedition){expedition=new Expedition({container:$('#expedition-canvas'),minimap:$('#minimap'),onTelemetry:updateTelemetry,onStage:updateStage,onInspect:inspectTerrain,onCompare:toggleEvidence,onPause:setPaused,onError:()=>{webglError($('#expedition-canvas'));toast('This device could not start the 3D renderer.',true);}});}
  if(!expedition.renderer)return;
  $('#expedition-loading').classList.remove('hidden');state.view='expedition';$$('.view').forEach(section=>section.classList.toggle('hidden',section.id!=='expedition-view'));$$('[data-view]').forEach(button=>button.classList.toggle('active',button.dataset.view==='expedition'));globe?.setActive(false);preview?.setActive(false);
  try{expedition.load(site,dataFor(site.id),statsFor(site.id));$('#expedition-title').textContent=site.name;$('#expedition-body').textContent=`${site.country.toUpperCase()} EXPEDITION`;$('#expedition-footnote').textContent=`${site.body==='moon'?'NASA LOLA':site.body==='mars'?'NASA MOLA':'Skadi terrain'} · 500 m sampled grid · 1 km slope baseline · Avatar enlarged; decorative rocks are not mapped hazards`;$('#pause-overlay').classList.add('hidden');$('#expedition-evidence').classList.add('hidden');$('#expedition-view').classList.remove('evidence-open');state.evidenceOpen=false;$$('[data-layer]').forEach(button=>button.classList.toggle('active',button.dataset.layer==='surface'));$('#terrain-legend').classList.add('hidden');if(matchMedia('(pointer:coarse)').matches){$('#expedition-view').classList.add('touch-mode');$('#touch-controls').classList.remove('hidden');}expedition.renderer.domElement.focus({preventScroll:true});}catch(error){toast(error.message,true);showView('explore');}finally{$('#expedition-loading').classList.add('hidden');}
}
function updateStage(phase){const explore=phase==='explore';$('#expedition-stage').textContent=explore?'Exploring':phase==='landing'?'Approach':'Deployment';$('#arrival-banner').classList.toggle('hidden',explore);$('#exploration-hud').classList.toggle('hidden',!explore);$('#deployment-progress').classList.toggle('hidden',explore);$('#deployment-progress').innerHTML=[['landing','Landing sequence'],['door','Payload door'],['robot','Deploy hexapod']].map(([id,text],i)=>{const done=phase==='deploy'&&i===0||explore,current=phase==='landing'&&i===0||phase==='deploy'&&i>0;return `<div class="deployment-step ${done?'done':current?'current':''}"><span class="step-dot">${done?'✓':i+1}</span>${text}</div>`;}).join('');$$('[data-phase]').forEach(el=>el.classList.toggle('active',el.dataset.phase===(phase==='landing'?'landing':explore?'explore':'deploy')));if(explore)toast('You have control. W/S to move, A/D to turn. E inspects the terrain.');}
function updateTelemetry(info){if(!info)return;latestTelemetry=info;$('#terrain-height').textContent=`${fmt(info.height,1)} m elevation`;$('#terrain-slope').textContent=`${fmt(info.slope,2)}° coarse slope · ${coord(info.lat,'N','S')}`;}
function setPaused(value){if(state.view!=='expedition')return;expedition?.setPaused(value);$('#pause-overlay').classList.toggle('hidden',!value);if(!value)expedition?.renderer?.domElement.focus({preventScroll:true});}
function toggleEvidence(){state.evidenceOpen=!state.evidenceOpen;$('#expedition-evidence').classList.toggle('hidden',!state.evidenceOpen);$('#expedition-view').classList.toggle('evidence-open',state.evidenceOpen);if(state.evidenceOpen)renderExpeditionEvidence();requestAnimationFrame(()=>expedition?.resize());}
function renderExpeditionEvidence(){const a=statsFor(state.targetId),b=statsFor(state.earthId);if(!a||!b)return;const e=earth(),result=compareTerrains(dataFor(state.targetId),dataFor(state.earthId),state.weights);$('#expedition-evidence').innerHTML=`<div class="evidence-header"><h2>Earth analog comparison</h2><button id="close-evidence" aria-label="Close comparison">${icon('close')}</button></div><div class="evidence-photo"><img src="${siteImage(e)}" alt="${esc(e.id==='wadi-rum'?'NASA orbital observation of Wadi Rum':e.name+' elevation hillshade')}"><div><h3>${esc(e.name)}</h3><p>${esc(e.country)} · Earth candidate</p></div></div><p class="evidence-copy">Terrain evidence compared with ${esc(target().name)}.</p><select id="expedition-earth-select" aria-label="Choose Earth analog candidate">${earthSites().map(s=>`<option value="${s.id}" ${s.id===e.id?'selected':''}>${esc(s.name)}</option>`).join('')}</select><div class="evidence-stat"><span>Mean coarse slope</span><strong>${fmt(a.slopeMean,2)}° / ${fmt(b.slopeMean,2)}°</strong></div><div class="evidence-stat"><span>Relative relief</span><strong>${fmt(a.relief)} / ${fmt(b.relief)} m</strong></div><div class="evidence-stat"><span>Terrain resemblance index</span><strong>${fmt(result.score,1)} / 100</strong></div>${profileSVG(a,b,{mini:true})}${miniLegend()}<p class="evidence-copy">Middle-row profiles, relative to each window minimum. Equal 32 km extents.</p><div class="limit-callout">${icon('warning')}<div><h3>Analogy limits</h3><p>Different gravity, atmosphere and radiation. Material and temperature equivalence are unassessed.</p></div></div><div class="source-chips">${sourceChip(target().sourceIds[0])}${sourceChip(e.sourceIds[0])}</div><button class="button button-primary" id="open-full-comparison">Open full comparison ${icon('arrow')}</button><button class="button button-outline" id="explore-earth-site">Explore ${esc(e.name)} in 3D</button>`;$('#close-evidence').onclick=toggleEvidence;$('#expedition-earth-select').onchange=e=>selectEarth(e.target.value);$('#open-full-comparison').onclick=()=>showView('compare');$('#explore-earth-site').onclick=()=>startExpedition(earth());}
function inspectTerrain(info=latestTelemetry){if(!info)return;openModal(`<p class="eyebrow">FIELD NOTEBOOK · TERRAIN SAMPLE</p><h2 id="modal-title">${esc(info.siteName)}</h2><p>${coordinates(info)}. Elevation is bilinearly sampled from the source grid. The slope describes kilometer-scale terrain, not a footstep or an individual rock.</p><div class="inspection-grid"><div><strong>${fmt(info.height,1)} m</strong><span>Elevation in source datum</span></div><div><strong>${fmt(info.slope,2)}°</strong><span>Coarse slope / 1 km baseline</span></div><div><strong>500 m</strong><span>Grid sampling interval</span></div><div><strong>${fmt(info.distanceMeters/1000,2)} km</strong><span>Map-equivalent navigation distance</span></div></div><label class="field-label" for="observation-note">Add a field note (optional)</label><textarea id="observation-note" class="note-input" maxlength="500" placeholder="What would you investigate at this location?"></textarea><span class="inspection-note">This is an observation of the dataset, not a new instrument measurement. Movement speed and the enlarged avatar do not represent a physical robot's capabilities.</span><button class="button button-primary" id="save-ground-observation">${icon('bookmark')} Save observation</button>`);$('#save-ground-observation').onclick=()=>{const observation={...info,note:$('#observation-note').value.trim(),savedAt:new Date().toISOString(),source:dataFor(info.siteId)?.source};state.observations.push(observation);try{localStorage.setItem('terramatch-observations',JSON.stringify(state.observations));}catch{toast('Observation saved for this session; browser storage is unavailable.',true);}closeModal();toast('Terrain observation added to your field notebook.');};}

function download(filename,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function evidenceObject(){const t=target(),e=earth();return{project:'TerraMatch',exportedAt:new Date().toISOString(),discovery:{selectedCandidateOrigin:e.origin||'reference',selectedCandidateSurvey:e.discovery||null,loadedSearchWindows:state.customSites.length,lastAutomaticSurvey:state.searchCoverage},target:t,candidate:e,comparison:compareTerrains(dataFor(t.id),dataFor(e.id),state.weights),weights:state.weights,method:METHOD,provenance:{target:dataFor(t.id).source,candidate:dataFor(e.id).source},observations:state.observations,notes:['Terrain-only resemblance, not mission suitability or probability.','Avatar enlarged; rocket and movement dynamics are illustrative.','Decorative rocks are not source observations.']};}
function exportEvidence(){if(!state.ready)return toast('Terrain data is still loading.',true);download(`terramatch-${state.targetId}-${state.earthId}-evidence.json`,JSON.stringify(evidenceObject(),null,2),'application/json');toast('Evidence JSON exported with source metadata.');}
function exportObservations(){download('terramatch-field-notebook.json',JSON.stringify({project:'TerraMatch',exportedAt:new Date().toISOString(),observations:state.observations},null,2),'application/json');toast(`${state.observations.length} observation${state.observations.length===1?'':'s'} exported.`);}
function exportReport(){if(!state.ready)return toast('Terrain data is still loading.',true);const r=evidenceObject(),a=r.comparison.targetStats,b=r.comparison.earthStats;const text=`# TerraMatch — Earth analog comparison\n\nGenerated: ${r.exportedAt}\n\n## Study areas\n\nPlanetary target: ${r.target.name} (${r.target.country}), ${coordinates(r.target)}.\n\nEarth candidate: ${r.candidate.name} (${r.candidate.country}), ${coordinates(r.candidate)}.\n\n## Measured terrain\n\nBoth study windows: 32 × 32 km;65 × 65 grid;500 m sampling;1 km slope baseline.\n\n| Measure | ${r.target.name} | ${r.candidate.name} |\n| --- | --- | --- |\n| Relative relief | ${fmt(a.relief,1)} m | ${fmt(b.relief,1)} m |\n| Mean coarse slope | ${fmt(a.slopeMean,2)}° | ${fmt(b.slopeMean,2)}° |\n| 90th percentile slope | ${fmt(a.slopeP90,2)}° | ${fmt(b.slopeP90,2)}° |\n\nTerrain resemblance index: ${r.comparison.score}/100. This is a transparent heuristic, not a probability of mission suitability.\n\nActive normalized weights: slope ${r.comparison.components[0].weight};relief ${r.comparison.components[1].weight}.\n\n## Method\n\nSlope distribution distance = total variation over [0,2,5,10,20,35,90] degree bins. Relief distance = min(1,abs(ln((relief A+1)/(relief B+1)))/ln(4)). Index = 100*(1-weighted distance).\n\n## Discovery provenance\n\nCandidate origin: ${r.candidate.origin||'curated reference'}.\n\n${r.candidate.discovery?'Selected candidate survey:\n\n'+JSON.stringify(r.candidate.discovery,null,2):'This candidate was selected manually or is a bundled reference. No global discovery claim is made.'}\n\n## Possible field uses\n\n${r.candidate.useCases.map(s=>'- '+s).join('\n')}\n\n## Limits\n\n${[...r.target.limitations,...r.candidate.limitations,...r.notes].map(s=>'- '+s).join('\n')}\n\nMaterials,temperature,ice,biology and field accessibility are unassessed. Coarse terrain resemblance requires further geological,field and operational assessment.\n\n## Sources\n\n${[...new Set([...r.target.sourceIds,...r.candidate.sourceIds])].map(id=>sourceById(id)).filter(Boolean).map(s=>`- ${s.title} — ${s.agency}\n  ${s.url}\n  ${s.license}`).join('\n\n')}\n\n## Exact terrain provenance\n\n\`\`\`json\n${JSON.stringify(r.provenance,null,2)}\n\`\`\`\n\n## Field notebook\n\n${state.observations.length?state.observations.map(o=>`- ${o.siteName},${coordinates(o)}: ${o.height.toFixed(1)} m elevation;${o.slope.toFixed(2)}° coarse slope. ${o.note||''}`).join('\n'):'No observations saved.'}\n\nCreated for NASA Space Apps Challenge2026. Public data use does not imply agency endorsement.\n`;download(`terramatch-${state.targetId}-${state.earthId}-report.md`,text,'text/markdown;charset=utf-8');toast('Comparison report exported with measurements and citations.');}

function bind(){
  $('#export-report').innerHTML=icon('download')+'Export report';$('#find-analogs').innerHTML=icon('search')+'Rank loaded candidates';$('#enter-expedition').innerHTML=icon('play')+'Explore in 3D';$('#compare-selected').innerHTML=icon('compare')+'Compare Earth analogs';$('#toggle-expedition-evidence').innerHTML=icon('compare')+'Earth comparison';$('#mission-robot-icon').innerHTML=icon('robot');
  $$('[data-view]').forEach(button=>button.onclick=()=>showView(button.dataset.view));$('.brand').onclick=e=>{e.preventDefault();showView('explore');};$$('[data-body]').forEach(button=>button.onclick=()=>setTarget(TARGETS.find(s=>s.body===button.dataset.body).id));$('#target-select').onchange=e=>setTarget(e.target.value);$('#task-select').onchange=e=>{state.task=e.target.value;};$$('[data-globe]').forEach(button=>button.onclick=()=>setGlobeBody(button.dataset.globe));$('#globe-reset').onclick=()=>globe?.reset();$('#globe-zoom-in').onclick=()=>globe?.zoom(-1);$('#globe-zoom-out').onclick=()=>globe?.zoom(1);
  $('#find-analogs').onclick=()=>{const slope=$('#metric-slope').checked,relief=$('#metric-relief').checked;if(!slope&&!relief){toast('Choose at least one terrain characteristic.',true);return;}state.weights={slope:slope?.65:0,relief:relief?.35:0};computeRankings();if(state.rankings.length)selectEarth(state.rankings[0].site.id);toast(`Compared ${state.rankings.length} inland candidates with ${target().name}.`);};
  $('#enter-expedition').onclick=()=>startExpedition();$('#compare-selected').onclick=()=>showView('compare');$('#export-report').onclick=exportReport;$('#compare-export').onclick=exportReport;$('#footer-sources').onclick=()=>showView('sources');$('#method-link').onclick=showMethod;$('#method-tip').onclick=showMethod;$('#material-note').onclick=()=>openModal(`<p class="eyebrow">SEPARATE THE EVIDENCE</p><h2 id="modal-title">Materials need their own evidence.</h2><p>The current ranking measures terrain slopes and relief. Geological descriptions and contextual references are available in Compare, but no mineral-equivalence score is calculated.</p><p>The challenge also permits temperature, ice, biology and other comparisons. Those require the relevant products and analysis before they can be measured here.</p>`);
  $('#take-control').onclick=()=>expedition?.skipArrival();$('#resume-expedition').onclick=()=>setPaused(false);$('#leave-expedition').onclick=()=>{setPaused(false);showView('explore');};$('#toggle-expedition-evidence').onclick=toggleEvidence;$('#camera-mode').onclick=()=>{if(expedition)$('#camera-mode').textContent=expedition.changeCamera()+' ↻';};$('#inspect-ground').onclick=()=>inspectTerrain();$('#expand-map').onclick=()=>$('.minimap').classList.toggle('expanded');
  $$('[data-layer]').forEach(button=>button.onclick=()=>{expedition?.setLayer(button.dataset.layer);$$('[data-layer]').forEach(b=>b.classList.toggle('active',b===button));$('#terrain-legend').classList.toggle('hidden',button.dataset.layer==='surface');if(button.dataset.layer==='elevation'){$('#terrain-legend>span:first-child').textContent='Low';$('#terrain-legend>span:last-child').textContent='High';}else{$('#terrain-legend>span:first-child').textContent='Gentle';$('#terrain-legend>span:last-child').textContent='Steep';}});
  $$('[data-move]').forEach(button=>{button.onpointerdown=e=>{e.preventDefault();button.setPointerCapture(e.pointerId);expedition?.setMove(button.dataset.move,true);};button.onpointerup=button.onpointercancel=()=>expedition?.setMove(button.dataset.move,false);});
}

let persistSearchTimer;
function browserStorage(){try{return window.localStorage;}catch{return null;}}
function persistSearchWindows(){const records=state.customSites.map(site=>({site,data:dataFor(site.id)}));if(!saveSearchWindows(browserStorage(),records))toast('Search results remain in this session; browser storage is full or unavailable.',true);}
function registerSearchWindow(record,{select=true,persist=true,render=true}={}){
  if(!validSearchWindow(record))throw new Error('The requested terrain window failed validation. No substitute data were added.');
  const {site,data}=record;const index=state.customSites.findIndex(item=>item.id===site.id);
  if(index>=0){const old=state.customSites[index];if(old.origin==='manual'&&site.origin==='automatic'){site.name=old.name;site.country=old.country;}state.customSites[index]=site;}else state.customSites.push(site);
  state.terrains.set(site.id,data);state.stats.set(site.id,analyzeTerrain(data));thumbs.delete(site.id);
  if(render&&state.ready){computeRankings();renderCandidates();renderDestination();if(state.globeBody==='earth')globe?.setSites(earthSites(),state.earthId);$('#data-status').textContent=state.terrains.size+' terrain windows · '+state.customSites.length+' searched';if(select&&site.comparisonEligible!==false)selectEarth(site.id);if(state.view==='compare')renderComparison();if(state.view==='sources')renderSources();}
  if(persist){clearTimeout(persistSearchTimer);persistSearchTimer=setTimeout(persistSearchWindows,300);}
}

async function init(){
  bind();$('#enter-expedition').disabled=true;$('#find-analogs').disabled=true;
  globe=new GlobeView({container:$('#globe-canvas'),onSelect:site=>{if(site.body==='earth')selectEarth(site.id);},onReady:()=>$('#globe-loading').classList.add('hidden'),onHover:(site,x,y)=>{const label=$('#globe-place-label');label.style.opacity=site?'1':'0';if(site){label.textContent=site.name;label.style.left=`${Math.max(12,Math.min($('.globe-panel').clientWidth-130,x+10))}px`;label.style.top=`${Math.max(68,y)}px`;}},onError:()=>{$('#globe-loading').classList.add('hidden');webglError($('#globe-canvas'));}});
  preview=createRobotPreview($('#robot-preview'));
  const results=await Promise.allSettled(SITES.map(async site=>{const data=await loadTerrain(site);state.terrains.set(site.id,data);state.stats.set(site.id,analyzeTerrain(data));}));
  results.forEach((result,index)=>{if(result.status==='rejected'){console.error(`Terrain ${SITES[index].id}:`,result.reason);toast(`${SITES[index].name} data could not be loaded.`,true);}});
  for(const record of restoreSearchWindows(browserStorage()))registerSearchWindow(record,{select:false,persist:false,render:false});
  state.ready=!!dataFor(state.targetId)&&!!dataFor(state.earthId);setTarget(state.targetId);globe?.setSites(earthSites(),state.earthId);$('#find-analogs').disabled=!state.ready;$('#data-status').textContent=`${state.terrains.size} real terrain windows · 500 m sampling`;$('#globe-loading').classList.add('hidden');
  searchUI=initSearchUI({onCandidate:registerSearchWindow,onSelect:selectEarth,onCompare:id=>{selectEarth(id);showView('compare');},onExplore:startExpedition,onSources:()=>showView('sources'),getTargetTerrain:()=>dataFor(state.targetId),getTargetName:()=>target().name,getWeights:()=>({...state.weights}),onPickMode:(mode,callback)=>{if(mode){setGlobeBody('earth');globe?.setSelectionMode(mode,callback);}else globe?.setSelectionMode(null);},onPreview:place=>{setGlobeBody('earth');globe?.focusSite(place);globe?.showSearchBounds(place.bounds);},onRegionPreview:bounds=>{setGlobeBody('earth');globe?.showSearchBounds(bounds);},onScanComplete:coverage=>{state.searchCoverage=coverage;for(const id of coverage.candidateIds||[]){const site=state.customSites.find(item=>item.id===id);if(site)site.discovery={type:'sampled-grid',regionName:coverage.regionName,bounds:coverage.bounds,stepDegrees:coverage.stepDegrees,planned:coverage.planned,completed:coverage.completed,failed:coverage.failed,excluded:coverage.excluded,targetId:coverage.targetId,targetName:coverage.targetName,weights:coverage.weights,exhaustive:false,status:coverage.cancelled?'cancelled-partial':'complete'};}clearTimeout(persistSearchTimer);persistSearchTimer=setTimeout(persistSearchWindows,300);},toast});
  window.__TERRAMATCH__={state,get expedition(){return expedition;},get searchUI(){return searchUI;},startExpedition,showView,exportEvidence,registerSearchWindow};
}
init().catch(error=>{console.error(error);toast('TerraMatch could not finish loading. Please reload the page.',true);$('#globe-loading').classList.add('hidden');});
